   224→  if (!job_id || !commit_sha) {
   225→    return Response.json({ error: 'Missing job_id or commit_sha' }, { status: 400 });
   226→  }
   227→
   228→  const { GH_OWNER, GH_REPO } = process.env;
   229→  const OBSIDIAN_HOST = getConfig('OBSIDIAN_HOST');
   230→  const OBSIDIAN_API_KEY = getConfig('OBSIDIAN_API_KEY');
   231→
   232→  if (!OBSIDIAN_HOST || !OBSIDIAN_API_KEY) {
   233→    return Response.json({ error: 'Obsidian not configured' }, { status: 500 });
   234→  }
   235→
   236→  try {
   237→    const files = await githubApi(
   238→      `/repos/${GH_OWNER}/${GH_REPO}/contents/logs/${job_id}?ref=${encodeURIComponent(commit_sha)}`
   239→    );
   240→
   241→    if (!Array.isArray(files)) {
   242→      return Response.json({ ok: true, synced: 0, reason: 'no log directory' });
   243→    }
   244→
   245→    const outputFiles = files.filter(f => f.name.endsWith('.md') && !VAULT_SKIP_FILES.has(f.name));
   246→    if (outputFiles.length === 0) {
   247→      return Response.json({ ok: true, synced: 0, reason: 'no output files' });
   248→    }
   249→
   250→    const synced = [];
   251→    for (const file of outputFiles) {
   252→      const fileData = await githubApi(
   253→        `/repos/${GH_OWNER}/${GH_REPO}/contents/logs/${job_id}/${file.name}?ref=${encodeURIComponent(commit_sha)}`
   254→      );
   255→      const content = Buffer.from(fileData.content, 'base64').toString('utf-8');
   256→
   257→      // Check frontmatter for explicit vault path
   258→      let vaultPath = `05-Agent-Outputs/${file.name}`;
   259→      const match = content.match(/^---\n[\s\S]*?vault-path:\s*(.+)\n[\s\S]*?---/);
   260→      if (match) vaultPath = match[1].trim();
   261→
   262→      const res = await fetch(`${OBSIDIAN_HOST}/vault/${vaultPath}`, {
   263→        method: 'PUT',
   264→        headers: { 'Authorization': `Bearer ${OBSIDIAN_API_KEY}`, 'Content-Type': 'text/markdown' },
   265→        body: content,
   266→      });
   267→
   268→      if (res.ok || res.status === 204) {
   269→        synced.push({ file: file.name, vault_path: vaultPath });
   270→        console.log(`[vault-sync] ${file.name} → ${vaultPath}`);
   271→      } else {
   272→        console.error(`[vault-sync] Failed: ${vaultPath} HTTP ${res.status}`);
   273→      }
   274→    }
   275→
   276→    console.log(`[vault-sync] Job ${job_id.slice(0, 8)}: ${synced.length}/${outputFiles.length} files`);
   277→    return Response.json({ ok: true, synced: synced.length, files: synced });
   278→  } catch (err) {
   279→    console.error('[vault-sync] Error:', err.message);
   280→    return Response.json({ error: 'Vault sync failed' }, { status: 500 });
   281→  }
   282→}
