   284→async function handleJobStatus(request) {
   285→  try {
   286→    const url = new URL(request.url);
   287→    const jobId = url.searchParams.get('job_id');
   288→    const result = await getJobStatus(jobId);
   289→    return Response.json(result);
   290→  } catch (err) {
   291→    console.error('Failed to get job status:', err);
   292→    return Response.json({ error: 'Failed to get job status' }, { status: 500 });
   293→  }
   294→}
   295→
   296→// ─────────────────────────────────────────────────────────────────────────────
   297→// Next.js Route Handlers (catch-all)
   298→// ─────────────────────────────────────────────────────────────────────────────
   299→
   300→async function POST(request) {
   301→  const url = new URL(request.url);
   302→  const routePath = url.pathname.replace(/^\/api/, '');
   303→
   304→  // Auth check
   305→  const authError = checkAuth(routePath, request);
   306→  if (authError) return authError;
   307→
   308→  // Fire triggers (non-blocking)
   309→  try {
   310→    const fireTriggers = getFireTriggers();
   311→    // Clone request to read body for triggers without consuming it for the handler
   312→    const clonedRequest = request.clone();
   313→    const body = await clonedRequest.json().catch(() => ({}));
   314→    const query = Object.fromEntries(url.searchParams);
   315→    const headers = Object.fromEntries(request.headers);
   316→    fireTriggers(routePath, body, query, headers);
   317→  } catch (e) {
   318→    // Trigger errors are non-fatal
   319→  }
   320→
   321→  // Cluster role webhooks
   322→  const clusterMatch = routePath.match(/^\/cluster\/([a-f0-9-]+)\/role\/([a-f0-9-]+)\/webhook$/);
   323→  if (clusterMatch) {
   324→    const { handleClusterWebhook } = await import('../lib/cluster/runtime.js');
   325→    return handleClusterWebhook(clusterMatch[1], clusterMatch[2], request);
   326→  }
   327→
   328→  // Route to handler
   329→  switch (routePath) {
   330→    case '/create-job':          return handleWebhook(request);
   331→    case '/vault-sync':          return handleVaultSync(request);
   332→    case '/telegram/webhook':   return handleTelegramWebhook(request);
   333→    case '/telegram/register':  return handleTelegramRegister(request);
   334→    case '/github/webhook':     return handleGithubWebhook(request);
   335→    default:                    return Response.json({ error: 'Not found' }, { status: 404 });
   336→  }
   337→}
   338→
   339→async function GET(request) {
   340→  const url = new URL(request.url);
   341→  const routePath = url.pathname.replace(/^\/api/, '');
   342→
   343→  // Auth check
   344→  const authError = checkAuth(routePath, request);
   345→  if (authError) return authError;
   346→
   347→  switch (routePath) {
   348→    case '/ping':           return Response.json({ message: 'Pong!' });
   349→    case '/jobs/status':    return handleJobStatus(request);
   350→    default:                return Response.json({ error: 'Not found' }, { status: 404 });
   351→  }
   352→}
   353→
   354→export { GET, POST };
   355→

