    10→
    11→function describeCron(schedule) {
    12→  const parts = schedule.trim().split(/\s+/);
    13→  if (parts.length !== 5) return schedule;
    14→
    15→  const [minute, hour, dayOfMonth, month, dayOfWeek] = parts;
    16→
    17→  // Every N minutes
    18→  if (minute.startsWith('*/') && hour === '*' && dayOfMonth === '*' && month === '*' && dayOfWeek === '*') {
    19→    const n = parseInt(minute.slice(2), 10);
    20→    if (n === 1) return 'Every minute';
    21→    return `Every ${n} minutes`;
    22→  }
    23→
    24→  // Every N hours
    25→  if (hour.startsWith('*/') && dayOfMonth === '*' && month === '*' && dayOfWeek === '*') {
    26→    const n = parseInt(hour.slice(2), 10);
    27→    if (n === 1) return 'Every hour';
    28→    return `Every ${n} hours`;
    29→  }
    30→
    31→  // Specific time daily
    32→  if (minute !== '*' && hour !== '*' && !hour.includes('/') && !minute.includes('/') && dayOfMonth === '*' && month === '*' && dayOfWeek === '*') {
    33→    const h = parseInt(hour, 10);
    34→    const m = parseInt(minute, 10);
    35→    const period = h >= 12 ? 'PM' : 'AM';
    36→    const displayH = h === 0 ? 12 : h > 12 ? h - 12 : h;
    37→    return `Daily at ${displayH}:${String(m).padStart(2, '0')} ${period}`;
    38→  }
    39→
    40→  // Specific time on specific weekdays
    41→  if (minute !== '*' && hour !== '*' && dayOfMonth === '*' && month === '*' && dayOfWeek !== '*') {
    42→    const dayNames = { '0': 'Sun', '1': 'Mon', '2': 'Tue', '3': 'Wed', '4': 'Thu', '5': 'Fri', '6': 'Sat' };
    43→    const days = dayOfWeek.split(',').map(d => dayNames[d] || d).join(', ');
    44→    const h = parseInt(hour, 10);
    45→    const m = parseInt(minute, 10);
    46→    const period = h >= 12 ? 'PM' : 'AM';
    47→    const displayH = h === 0 ? 12 : h > 12 ? h - 12 : h;
    48→    return `${days} at ${displayH}:${String(m).padStart(2, '0')} ${period}`;
    49→  }
    50→
    51→  return schedule;
    52→}
    53→
    54→const typeBadgeStyles = {
    55→  agent: 'bg-purple-500/10 text-purple-500',
    56→  command: 'bg-blue-500/10 text-blue-500',
    57→  webhook: 'bg-orange-500/10 text-orange-500',
    58→};
    59→
    60→const typeOrder = { agent: 0, command: 1, webhook: 2 };
    61→
    62→function sortByType(items) {
    63→  return [...items].sort((a, b) => {
    64→    const ta = typeOrder[a.type || 'agent'] ?? 99;
    65→    const tb = typeOrder[b.type || 'agent'] ?? 99;
    66→    return ta - tb;
    67→  });
    68→}
    69→
    70→// ─────────────────────────────────────────────────────────────────────────────
    71→// Group Header
    72→// ─────────────────────────────────────────────────────────────────────────────
    73→
    74→function GroupHeader({ label, count }) {
    75→  return (
    76→    <div className="flex items-center gap-2 pt-2 pb-1">
    77→      <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">{label}</span>
    78→      <span className="text-xs text-muted-foreground">({count})</span>
    79→    </div>
    80→  );
    81→}
    82→
    83→// ─────────────────────────────────────────────────────────────────────────────
    84→// Cron Card
    85→// ─────────────────────────────────────────────────────────────────────────────
    86→
    87→function CronCard({ cron }) {
    88→  const [expanded, setExpanded] = useState(false);
    89→  const type = cron.type || 'agent';
    90→  const disabled = cron.enabled === false;
    91→
    92→  return (
    93→    <div
    94→      className={`rounded-lg border bg-card transition-opacity ${disabled ? 'opacity-60' : ''}`}
    95→    >
    96→      <button
    97→        onClick={() => setExpanded(!expanded)}
    98→        className="flex items-center gap-3 w-full text-left p-4 hover:bg-accent/50 rounded-lg"
    99→      >
   100→        <div className="shrink-0 rounded-md bg-muted p-2">
   101→          <ClockIcon size={16} />
   102→        </div>
   103→        <div className="flex-1 min-w-0">
   104→          <p className="text-sm font-medium truncate">{cron.name}</p>
   105→          <p className="text-xs text-muted-foreground mt-0.5">
   106→            <span className="font-mono">{cron.schedule}</span>
   107→            <span className="mx-1.5 text-border">|</span>
   108→            {describeCron(cron.schedule)}
   109→          </p>
   110→        </div>
   111→        <div className="flex items-center gap-2 shrink-0 flex-wrap justify-end">
   112→          <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-medium ${typeBadgeStyles[type] || typeBadgeStyles.agent}`}>
   113→            {type}
   114→          </span>
   115→          <span
   116→            className={`inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-medium ${
   117→              disabled ? 'bg-muted text-muted-foreground' : 'bg-green-500/10 text-green-500'
   118→            }`}
   119→          >
   120→            {disabled ? 'disabled' : 'enabled'}
   121→          </span>
   122→          <span className={`transition-transform ${expanded ? 'rotate-180' : ''}`}>
   123→            <ChevronDownIcon size={14} />
   124→          </span>
   125→        </div>
   126→      </button>
   127→
   128→      {expanded && (
   129→        <div className="border-t px-4 py-3">
   130→          {type === 'agent' && cron.job && (
   131→            <div>
   132→              <p className="text-xs font-medium text-muted-foreground mb-1.5">Job prompt</p>
   133→              <pre className="text-xs bg-muted rounded-md p-3 whitespace-pre-wrap break-words font-mono overflow-auto max-h-48">
   134→                {cron.job}
   135→              </pre>
   136→              {(cron.llm_provider || cron.llm_model) && (
   137→                <div className="flex items-center gap-2 mt-2">
   138→                  <span className="text-xs font-medium text-muted-foreground">LLM:</span>
   139→                  <span className="inline-flex items-center rounded-full bg-purple-500/10 text-purple-500 px-2 py-0.5 text-[10px] font-medium">
   140→                    {[cron.llm_provider, cron.llm_model].filter(Boolean).join(' / ')}
   141→                  </span>
   142→                </div>
   143→              )}
   144→            </div>
   145→          )}
   146→          {type === 'command' && cron.command && (
   147→            <div>
   148→              <p className="text-xs font-medium text-muted-foreground mb-1.5">Command</p>
   149→              <pre className="text-xs bg-muted rounded-md p-3 whitespace-pre-wrap break-words font-mono overflow-auto max-h-48">
   150→                {cron.command}
   151→              </pre>
   152→            </div>
   153→          )}
   154→          {type === 'webhook' && (
   155→            <div className="flex flex-col gap-2">
   156→              <div>
   157→                <p className="text-xs font-medium text-muted-foreground mb-1.5">URL</p>
   158→                <pre className="text-xs bg-muted rounded-md p-3 whitespace-pre-wrap break-words font-mono overflow-auto">
   159→                  {cron.method && cron.method !== 'POST' ? `${cron.method} ` : ''}{cron.url}
   160→                </pre>
   161→              </div>
   162→              {cron.vars && Object.keys(cron.vars).length > 0 && (
   163→                <div>
   164→                  <p className="text-xs font-medium text-muted-foreground mb-1.5">Variables</p>
   165→                  <pre className="text-xs bg-muted rounded-md p-3 whitespace-pre-wrap break-words font-mono overflow-auto max-h-48">
   166→                    {JSON.stringify(cron.vars, null, 2)}
   167→                  </pre>
   168→                </div>
   169→              )}
   170→            </div>
   171→          )}
   172→        </div>
   173→      )}
   174→    </div>
   175→  );
   176→}
   177→
   178→// ─────────────────────────────────────────────────────────────────────────────
   179→// Main Page
   180→// ─────────────────────────────────────────────────────────────────────────────
   181→
   182→export function CronsPage() {
   183→  const [crons, setCrons] = useState([]);
   184→  const [loading, setLoading] = useState(true);
   185→
   186→  useEffect(() => {
   187→    getRunnersConfig()
   188→      .then((data) => {
   189→        if (data?.crons) setCrons(data.crons);
   190→      })
   191→      .catch(() => {})
   192→      .finally(() => setLoading(false));
