   267→    console.error('Failed to delete API key:', err);
   268→    return { error: 'Failed to delete API key' };
   269→  }
   270→}
   271→
   272→// ─────────────────────────────────────────────────────────────────────────────
   273→// OAuth Token actions
   274→// ─────────────────────────────────────────────────────────────────────────────
   275→
   276→/**
   277→ * Create a new named OAuth token.
   278→ * @param {string} name - Human-readable name
   279→ * @param {string} token - Raw OAuth token
   280→ * @returns {Promise<{ id: string, name: string, createdAt: number, lastUsedAt: null } | { error: string }>}
   281→ */
   282→export async function createOAuthToken(name, token) {
   283→  const user = await requireAuth();
   284→  try {
   285→    const { createOAuthToken: dbCreate } = await import('../db/oauth-tokens.js');
   286→    const { invalidateConfigCache } = await import('../config.js');
   287→    const result = dbCreate(name || 'OAuth Token', token, user.id);
   288→    invalidateConfigCache();
   289→    return result;
   290→  } catch (err) {
   291→    console.error('Failed to create OAuth token:', err);
   292→    return { error: 'Failed to create OAuth token' };
   293→  }
   294→}
   295→
   296→/**
   297→ * List all OAuth tokens (metadata only).
