   814→// Known GitHub secrets and variables (mirrors setup/lib/targets.mjs)
   815→const GITHUB_SECRETS = [
   816→  { name: 'AGENT_GH_TOKEN', label: 'GitHub Token' },
   817→  { name: 'AGENT_ANTHROPIC_API_KEY', label: 'Anthropic API Key' },
   818→  { name: 'AGENT_OPENAI_API_KEY', label: 'OpenAI API Key' },
   819→  { name: 'AGENT_GOOGLE_API_KEY', label: 'Google API Key' },
   820→  { name: 'AGENT_CUSTOM_API_KEY', label: 'Custom API Key' },
   821→  { name: 'AGENT_CLAUDE_CODE_OAUTH_TOKEN', label: 'Claude Code OAuth' },
   822→  { name: 'AGENT_LLM_BRAVE_API_KEY', label: 'Brave API Key' },
   823→  { name: 'GH_WEBHOOK_SECRET', label: 'Webhook Secret' },
   824→];
   825→
   826→const GITHUB_VARIABLES = [
   827→  { name: 'LLM_PROVIDER', label: 'LLM Provider' },
   828→  { name: 'LLM_MODEL', label: 'LLM Model' },
   829→  { name: 'OPENAI_BASE_URL', label: 'OpenAI Base URL' },
   830→  { name: 'AGENT_BACKEND', label: 'Agent Backend' },
   831→  { name: 'AUTO_MERGE', label: 'Auto Merge' },
   832→  { name: 'ALLOWED_PATHS', label: 'Allowed Paths' },
   833→  { name: 'RUNS_ON', label: 'Runs On' },
   834→  { name: 'APP_URL', label: 'App URL' },
   835→];
   836→
   837→/**
   838→ * Get GitHub secrets and variables config.
   839→ * Fetches real lists from GitHub API and merges with known names.
   840→ */
   841→export async function getGitHubConfig() {
   842→  await requireAuth();
   843→  const { getConfig } = await import('../config.js');
   844→  const token = getConfig('GH_TOKEN');
   845→  const owner = process.env.GH_OWNER;
   846→  const repo = process.env.GH_REPO;
   847→
   848→  if (!token || !owner || !repo) {
   849→    return { error: 'GitHub not configured' };
   850→  }
   851→
   852→  const { listGitHubSecrets, listGitHubVariables } = await import('../github-api.js');
   853→
   854→  // Fetch actual secrets/variables from GitHub (names only for secrets)
   855→  const [remoteSecrets, remoteVariables] = await Promise.all([
   856→    listGitHubSecrets(),
   857→    listGitHubVariables(),
   858→  ]);
   859→
   860→  // Build secrets list: known names + any extras from GitHub, with isSet flag
   861→  const remoteSecretNames = new Set(
   862→    Array.isArray(remoteSecrets) ? remoteSecrets.map((s) => s.name) : []
   863→  );
   864→  const secrets = GITHUB_SECRETS.map((s) => ({ ...s, isSet: remoteSecretNames.has(s.name) }));
   865→  // Add any secrets on GitHub that aren't in our known list
   866→  for (const name of remoteSecretNames) {
   867→    if (!GITHUB_SECRETS.find((s) => s.name === name)) {
   868→      secrets.push({ name, isSet: true });
   869→    }
   870→  }
   871→
   872→  // Build variables list: known names + any extras, with current value
   873→  const remoteVarMap = new Map(
