import { notFound } from 'next/navigation';
import QRCode from 'qrcode';
import { getPicklistById, getPicklistOrderIds } from 'thepopebot/db/picklists';
import { getOrdersByIds } from 'thepopebot/db/orders';
import { generatePicklistHtml, groupBySku } from 'thepopebot/picklist';
import { markPicklistPrinted } from 'thepopebot/db/picklists';

/**
 * Print-friendly picklist view.
 * Accessible without auth so warehouse scanners can open it directly.
 * Marks picklist as 'printed' on load.
 */
export default async function PrintPicklistPage({ params }) {
  const { id } = await params;

  const picklist = getPicklistById(id);
  if (!picklist) notFound();

  // Mark as printed on first view
  if (picklist.status === 'pending') {
    markPicklistPrinted(id);
  }

  const orderIds = getPicklistOrderIds(id);
  const ordersWithItems = getOrdersByIds(orderIds);

  // Build scan URL (the QR code points back to the scan API)
  const appUrl = process.env.APP_URL || 'http://localhost:3000';
  const scanUrl = `${appUrl}/api/picklist/scan?id=${id}`;

  // Generate QR code as inline SVG
  let qrSvg = '';
  try {
    qrSvg = await QRCode.toString(scanUrl, { type: 'svg', width: 80, margin: 1 });
  } catch {
    qrSvg = `<div style="width:80px;height:80px;border:1px solid #ccc;display:flex;align-items:center;justify-content:center;font-size:10px;color:#999;">QR</div>`;
  }

  const html = generatePicklistHtml(picklist, ordersWithItems, qrSvg, scanUrl);

  return (
    <html lang="en">
      <head>
        <meta charSet="UTF-8" />
        <title>Picklist {id.slice(0, 8).toUpperCase()}</title>
        <style>{`
          @media print {
            @page { margin: 10mm; size: A4; }
          }
          .print-controls {
            position: fixed; top: 12px; right: 12px; z-index: 999;
            display: flex; gap: 8px;
            background: white; padding: 8px; border-radius: 8px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.15);
          }
          .print-controls button {
            padding: 6px 14px; border-radius: 6px; cursor: pointer;
            font-size: 13px; font-weight: 600; border: 1px solid #ccc;
            background: #111; color: #fff;
          }
          .print-controls button.secondary {
            background: transparent; color: #111;
          }
          @media print { .print-controls { display: none !important; } }
        `}</style>
      </head>
      <body>
        <div className="print-controls">
          <button onClick="window.print()" type="button">Print</button>
          <button className="secondary" onClick="window.close()" type="button">Close</button>
        </div>
        <div dangerouslySetInnerHTML={{ __html: html }} />
        <script dangerouslySetInnerHTML={{ __html: 'document.querySelector("[onClick]") && void 0;' }} />
      </body>
    </html>
  );
}

